window.__ModuleLoader__.load({
  id: '@local/whale-companion',
  factory(require) {
    const React = require('react');
    const h = React.createElement;

    const NS = 'whaleCompanion';
    const REFRESH_MS = 30000;
    const ROTATE_MS = 60000;

    // Square previews from the DeepSeek-chan meme pack (GengJing). Every square
    // image qualifies; the one near-square image (052) is center-cropped.
    const ARTS = [
      { id: '007', src: 'data:image/webp;base64,' },
      { id: '010', src: 'data:image/webp;base64,' },
      { id: '022', src: 'data:image/webp;base64,' },
      { id: '035', src: 'data:image/webp;base64,' },
      { id: '037', src: 'data:image/webp;base64,' },
      { id: '040', src: 'data:image/webp;base64,' },
      { id: '044', src: 'data:image/webp;base64,' },
      { id: '050', src: 'data:image/webp;base64,' },
      { id: '070', src: 'data:image/webp;base64,' },
      { id: '071', src: 'data:image/webp;base64,' },
      { id: '077', src: 'data:image/webp;base64,' },
      { id: '081', src: 'data:image/webp;base64,' },
      { id: '083', src: 'data:image/webp;base64,' },
      { id: '085', src: 'data:image/webp;base64,' },
      { id: '123', src: 'data:image/webp;base64,' },
      { id: '052', src: 'data:image/webp;base64,' },
    ];

    const MODES = ['sequence', 'random', 'manual'];

    const DICTS = {
      en: {
        title: 'Whale companion',
        balance: 'Balance',
        bonus: 'bonus',
        loading: 'counting coins…',
        signedOut: 'sign in to see the balance',
        unavailable: 'balance unavailable',
        failed: 'cannot read the balance now',
        refresh: 'Refresh balance',
        refreshHint: 'click to refresh',
        updated: 'Updated at',
        prev: 'Previous whale',
        next: 'Next whale',
        switchHint: 'Click for the next whale · Shift+click for a random one',
        modeSequence: 'auto · in order',
        modeRandom: 'auto · random',
        modeManual: 'manual',
        modeHint: 'Switch how the whale changes (in order → random → manual)',
        credit: 'Art from the DeepSeek-chan meme pack (GengJing), fan-made',
      },
      zh: {
        title: '鲸鱼娘余额伙伴',
        balance: '余额',
        bonus: '赠送',
        loading: '正在数硬币…',
        signedOut: '登录后就能看到余额啦',
        unavailable: '余额暂时不可用',
        failed: '这会儿读不到余额',
        refresh: '刷新余额',
        refreshHint: '点击刷新',
        updated: '更新于',
        prev: '上一张',
        next: '下一张',
        switchHint: '点一下换一只鲸鱼娘 · Shift+点击随机换',
        modeSequence: '自动·顺序',
        modeRandom: '自动·随机',
        modeManual: '手动',
        modeHint: '切换鲸鱼娘出现方式（顺序 → 随机 → 手动）',
        credit: '形象来自「蓝色大肥鱼」表情包合集（梗鲸 GengJing），非商用粉丝创作',
      },
    };

    const SYMBOLS = { CNY: '¥', USD: '$' };

    const CSS = `
.dsh-wc {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 234px;
  pointer-events: none;
  font-family: inherit;
}
.dsh-wc__art {
  pointer-events: auto;
  flex: 0 0 auto;
  width: 204px;
  height: 204px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 28px;
  background: #ffffff;
  box-shadow:
    0 0 0 4px var(--dsw-alias-bg-layer-1),
    0 14px 40px rgba(16, 42, 67, 0.22);
  cursor: pointer;
  overflow: hidden;
  line-height: 0;
  transition: box-shadow 0.2s ease;
}
.dsh-wc__art:hover {
  box-shadow:
    0 0 0 4px var(--dsw-alias-brand-primary),
    0 18px 46px rgba(16, 42, 67, 0.28);
}
.dsh-wc__art:active {
  transform: scale(0.99);
}
.dsh-wc__art:focus-visible {
  outline: 3px solid var(--dsw-alias-brand-primary);
  outline-offset: 6px;
}
.dsh-wc__art img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  animation: dsh-wc-pop 0.28s ease;
}
.dsh-wc__card {
  pointer-events: auto;
  position: relative;
  box-sizing: border-box;
  width: 100%;
  margin-top: 15px;
  padding: 15px 18px 12px;
  border: 1px solid var(--dsw-alias-border-l1);
  border-radius: 21px;
  background: var(--dsw-alias-bg-overlay);
  box-shadow: 0 12px 36px rgba(16, 42, 67, 0.18);
  text-align: left;
  transition: opacity 0.2s ease;
}
.dsh-wc__card--stale {
  opacity: 0.62;
}
.dsh-wc__card::before {
  content: '';
  position: absolute;
  top: -8px;
  left: 50%;
  width: 14px;
  height: 14px;
  margin-left: -7px;
  background: var(--dsw-alias-bg-overlay);
  border-left: 1px solid var(--dsw-alias-border-l1);
  border-top: 1px solid var(--dsw-alias-border-l1);
  border-top-left-radius: 3px;
  transform: rotate(45deg);
}
.dsh-wc__label {
  display: block;
  font-size: 23px;
  line-height: 1.2;
  letter-spacing: 0.04em;
  color: var(--dsw-alias-label-secondary);
}
.dsh-wc__amount {
  margin-top: 3px;
  font-size: 38px;
  font-weight: 600;
  line-height: 1.15;
  color: var(--dsw-alias-label-primary);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  cursor: pointer;
}
.dsh-wc__amount--muted {
  font-size: 24px;
  font-weight: 500;
  line-height: 1.35;
  white-space: normal;
  color: var(--dsw-alias-label-secondary);
}
.dsh-wc__amount--warn {
  font-size: 24px;
  font-weight: 500;
  line-height: 1.35;
  white-space: normal;
  color: var(--dsw-alias-state-warn-primary);
}
.dsh-wc__bonus {
  display: block;
  margin-top: 4px;
  font-size: 22px;
  font-weight: 600;
  line-height: 1.25;
  color: var(--dsw-alias-state-success-primary);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.dsh-wc__controls {
  display: flex;
  align-items: center;
  gap: 3px;
  margin-top: 12px;
  padding-top: 9px;
  border-top: 1px solid var(--dsw-alias-border-l1);
  opacity: 0.55;
  transition: opacity 0.15s ease;
}
.dsh-wc:hover .dsh-wc__controls,
.dsh-wc:focus-within .dsh-wc__controls {
  opacity: 1;
}
.dsh-wc__ctrl {
  flex: 0 0 auto;
  margin: 0;
  padding: 5px 8px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: var(--dsw-alias-label-secondary);
  font: inherit;
  font-size: 26px;
  line-height: 1;
  cursor: pointer;
}
.dsh-wc__ctrl:hover {
  background: var(--dsw-alias-bg-layer-2);
  color: var(--dsw-alias-label-primary);
}
.dsh-wc__ctrl:focus-visible {
  outline: 2px solid var(--dsw-alias-brand-primary);
  outline-offset: 2px;
}
.dsh-wc__mode {
  flex: 1 1 auto;
  min-width: 0;
  padding: 5px 6px;
  font-size: 22px;
  letter-spacing: 0.01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
@keyframes dsh-wc-pop {
  from { opacity: 0; transform: scale(1.03); }
  to { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
  .dsh-wc__art img { animation: none; }
  .dsh-wc__card, .dsh-wc__controls { transition: none; }
}
@media (max-width: 720px) {
  .dsh-wc { right: 14px; bottom: 14px; width: 190px; }
  .dsh-wc__art { width: 166px; height: 166px; border-radius: 23px; }
  .dsh-wc__label { font-size: 18px; }
  .dsh-wc__amount { font-size: 30px; }
  .dsh-wc__amount--muted, .dsh-wc__amount--warn { font-size: 19px; }
  .dsh-wc__bonus { font-size: 17px; }
  .dsh-wc__ctrl { font-size: 21px; }
  .dsh-wc__mode { font-size: 17px; }
}
`;

    return {
      inject: ['slots', 'locale', 'remote', 'remote.account', 'remoteAccess'],
      apply(ctx) {
        const state = {
          phase: 'loading',
          wallets: [],
          bonusWallets: [],
          stale: false,
          updatedAt: 0,
          art: 0,
          mode: 'sequence',
        };
        const listeners = new Set();
        let hovering = false;
        let artTimer = 0;

        const publish = (patch) => {
          Object.assign(state, patch);
          for (const listener of Array.from(listeners)) {
            try {
              listener();
            } catch (error) {
              console.error('[whale-companion] listener failed', error);
            }
          }
        };

        ctx.effect(() => ctx.locale.register(NS, DICTS), 'whale: dictionaries');
        const t = ctx.locale.bind(NS);
        const tr = (key, fallback) => {
          const value = t(key);
          if (value !== key) return value;
          return fallback ?? key;
        };

        const scheduleArt = () => {
          if (artTimer !== 0) {
            window.clearInterval(artTimer);
            artTimer = 0;
          }
          if (state.mode === 'manual') return;
          artTimer = window.setInterval(() => {
            if (hovering || document.visibilityState === 'hidden') return;
            showArt(state.mode === 'random');
          }, ROTATE_MS);
        };

        const nextIndex = (random) => {
          const total = ARTS.length;
          if (total < 2) return 0;
          if (!random) return (state.art + 1) % total;
          let candidate = state.art;
          while (candidate === state.art) candidate = Math.floor(Math.random() * total);
          return candidate;
        };

        const showArt = (random) => {
          publish({ art: nextIndex(random === true) });
        };

        const cycleMode = () => {
          const current = MODES.indexOf(state.mode);
          publish({ mode: MODES[(current + 1) % MODES.length] });
          scheduleArt();
        };

        ctx.effect(() => {
          scheduleArt();
          return () => {
            if (artTimer !== 0) {
              window.clearInterval(artTimer);
              artTimer = 0;
            }
          };
        }, 'whale: art rotation');

        const version = () => {
          try {
            const boot = globalThis.__DSH_BOOT__;
            const candidates = [
              boot && boot.release && boot.release.version,
              boot && boot.graph && boot.graph.release && boot.graph.release.version,
              boot && boot.version,
            ];
            for (const candidate of candidates) {
              if (typeof candidate === 'string' && candidate.length > 0) return candidate;
            }
          } catch {
            // A missing boot payload only means the version stays generic.
          }
          return '0.0.0';
        };

        const clientMetadata = () => {
          let locale = 'en';
          try {
            locale = ctx.locale.getSnapshot().active || locale;
          } catch {
            // Keep the neutral locale.
          }
          return {
            version: version(),
            locale,
            timezoneOffsetSeconds: -new Date().getTimezoneOffset() * 60,
          };
        };

        let timer = 0;
        let reading = false;
        let disposed = false;

        const readOnce = async () => {
          if (reading || disposed) return;
          if (document.visibilityState === 'hidden') return;
          reading = true;
          try {
            const account = ctx.remote && ctx.remote.account;
            if (!account) {
              publish({ phase: 'unavailable', stale: false });
              return;
            }
            const result = await account.getBalance(clientMetadata());
            if (disposed) return;
            if (!result || result.ok !== true) {
              publish({ phase: state.phase === 'ready' ? 'ready' : 'unavailable', stale: true });
              return;
            }
            const value = result.value;
            if (value === null || value === undefined) {
              publish({ phase: 'signed-out', wallets: [], bonusWallets: [], stale: false, updatedAt: 0 });
              return;
            }
            if (value.status === 'failed') {
              publish({ phase: 'failed', stale: false });
              return;
            }
            publish({
              phase: 'ready',
              wallets: Array.isArray(value.value) ? value.value : [],
              bonusWallets: Array.isArray(value.bonusWallets) ? value.bonusWallets : [],
              stale: false,
              updatedAt: Date.now(),
            });
          } catch (error) {
            if (!disposed) {
              console.error('[whale-companion] balance read failed', error);
              publish({ phase: state.phase === 'ready' ? 'ready' : 'unavailable', stale: true });
            }
          } finally {
            reading = false;
          }
        };

        const startPolling = () => {
          void readOnce();
          if (timer === 0) timer = window.setInterval(() => void readOnce(), REFRESH_MS);
          return () => {
            if (timer !== 0) {
              window.clearInterval(timer);
              timer = 0;
            }
          };
        };

        ctx.effect(
          () =>
            ctx.remoteAccess.whenAccess('account/watch', () => {
              const stop = startPolling();
              return () => {
                stop();
                publish({ phase: 'loading', wallets: [], bonusWallets: [], stale: false, updatedAt: 0 });
              };
            }),
          'whale: account access',
        );

        ctx.effect(() => {
          const onVisibility = () => {
            if (document.visibilityState === 'visible') void readOnce();
          };
          document.addEventListener('visibilitychange', onVisibility);
          return () => document.removeEventListener('visibilitychange', onVisibility);
        }, 'whale: visibility refresh');

        ctx.effect(
          () => () => {
            disposed = true;
          },
          'whale: lifetime',
        );

        const number = (wallet) => {
          const amount = Number(wallet.balance);
          return Number.isFinite(amount) ? amount : null;
        };

        const formatWallet = (wallet) => {
          const symbol = SYMBOLS[wallet.currency] ?? '';
          const amount = number(wallet);
          if (amount === null) return `${symbol}${wallet.balance}`;
          if (amount > 0 && amount < 0.01) return `${symbol}<0.01`;
          if (amount < 0 && amount > -0.01) return `${symbol}-0.01`;
          return `${symbol}${amount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
        };

        const primaryWallet = (wallets) => wallets.find((wallet) => wallet.currency === 'CNY') ?? wallets[0] ?? null;

        const bonusText = () => {
          const wallet = primaryWallet(state.wallets);
          if (!wallet) return null;
          const bonus = state.bonusWallets.filter(
            (entry) => entry.currency === wallet.currency && (number(entry) ?? 0) > 0,
          );
          if (bonus.length === 0) return null;
          const total = bonus.reduce((sum, entry) => sum + (number(entry) ?? 0), 0);
          return `+ ${tr('bonus', 'bonus')} ${SYMBOLS[wallet.currency] ?? ''}${total.toLocaleString('en-US', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
          })}`;
        };

        const modeLabel = () => {
          if (state.mode === 'random') return tr('modeRandom', 'auto · random');
          if (state.mode === 'manual') return tr('modeManual', 'manual');
          return tr('modeSequence', 'auto · in order');
        };

        // A very long formatted amount keeps the 2x type scale but steps down so
        // it never spills out of the card.
        const amountStyle = (text) => {
          const length = String(text).length;
          if (length <= 9) return undefined;
          return { fontSize: length <= 12 ? '30px' : '24px' };
        };

        function WhaleCompanion() {
          const [, bump] = React.useState(0);
          React.useEffect(() => {
            const listener = () => bump((value) => value + 1);
            listeners.add(listener);
            return () => listeners.delete(listener);
          }, []);
          React.useEffect(() => ctx.locale.subscribe(() => bump((value) => value + 1)), []);

          const art = ARTS[state.art % ARTS.length];
          const wallet = state.phase === 'ready' ? primaryWallet(state.wallets) : null;
          let amountNode;
          if (state.phase === 'ready' && wallet) {
            const text = formatWallet(wallet);
            amountNode = h('div', { className: 'dsh-wc__amount', style: amountStyle(text) }, text);
          } else if (state.phase === 'ready') {
            amountNode = h('div', { className: 'dsh-wc__amount dsh-wc__amount--muted' }, '—');
          } else if (state.phase === 'signed-out') {
            amountNode = h('div', { className: 'dsh-wc__amount dsh-wc__amount--muted' }, tr('signedOut', 'sign in'));
          } else if (state.phase === 'failed') {
            amountNode = h('div', { className: 'dsh-wc__amount dsh-wc__amount--warn' }, tr('failed', 'failed'));
          } else if (state.phase === 'unavailable') {
            amountNode = h('div', { className: 'dsh-wc__amount dsh-wc__amount--muted' }, tr('unavailable', 'unavailable'));
          } else {
            amountNode = h('div', { className: 'dsh-wc__amount dsh-wc__amount--muted' }, tr('loading', 'loading…'));
          }

          const bonus = state.phase === 'ready' ? bonusText() : null;
          const updated = state.updatedAt
            ? `${tr('updated', 'Updated at')} ${new Date(state.updatedAt).toLocaleTimeString([], {
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
              })}`
            : tr('refresh', 'Refresh balance');

          return h(
            'div',
            {
              className: 'dsh-wc',
              role: 'group',
              'aria-label': tr('title', 'Whale companion'),
              onMouseEnter: () => {
                hovering = true;
              },
              onMouseLeave: () => {
                hovering = false;
              },
            },
            h('style', { key: 'styles' }, CSS),
            h(
              'button',
              {
                key: 'art',
                type: 'button',
                className: 'dsh-wc__art',
                title: `${tr('switchHint', 'next whale')}\n#${art.id} · ${tr('credit', '')}`.trim(),
                'aria-label': tr('next', 'Next whale'),
                onClick: (event) => {
                  showArt(event.shiftKey);
                  scheduleArt();
                },
              },
              h('img', { key: art.id, src: art.src, alt: '', draggable: 'false' }),
            ),
            h(
              'div',
              { key: 'card', className: state.stale ? 'dsh-wc__card dsh-wc__card--stale' : 'dsh-wc__card' },
              h('span', { className: 'dsh-wc__label' }, tr('balance', 'Balance')),
              h(
                'div',
                {
                  title: `${updated} · ${tr('refreshHint', 'click to refresh')}`,
                  onClick: () => void readOnce(),
                  role: 'status',
                  'aria-live': 'polite',
                },
                amountNode,
              ),
              bonus ? h('span', { className: 'dsh-wc__bonus' }, bonus) : null,
              h(
                'div',
                { key: 'controls', className: 'dsh-wc__controls' },
                h(
                  'button',
                  {
                    type: 'button',
                    className: 'dsh-wc__ctrl',
                    title: tr('prev', 'Previous'),
                    'aria-label': tr('prev', 'Previous'),
                    onClick: (event) => {
                      event.stopPropagation();
                      publish({ art: (state.art - 1 + ARTS.length) % ARTS.length });
                      scheduleArt();
                    },
                  },
                  '‹',
                ),
                h(
                  'button',
                  {
                    type: 'button',
                    className: 'dsh-wc__ctrl dsh-wc__mode',
                    title: tr('modeHint', 'change rotation'),
                    'aria-label': tr('modeHint', 'change rotation'),
                    onClick: (event) => {
                      event.stopPropagation();
                      cycleMode();
                    },
                  },
                  modeLabel(),
                ),
                h(
                  'button',
                  {
                    type: 'button',
                    className: 'dsh-wc__ctrl',
                    title: tr('next', 'Next'),
                    'aria-label': tr('next', 'Next'),
                    onClick: (event) => {
                      event.stopPropagation();
                      showArt(false);
                      scheduleArt();
                    },
                  },
                  '›',
                ),
              ),
            ),
          );
        }

        ctx.slots.inject('shell.overlay', () =>
          ctx.slots.register(
            {
              name: 'shell.overlay',
              id: 'whale-companion',
              order: 30,
              label: () => tr('title', 'Whale companion'),
            },
            WhaleCompanion,
          ),
        );
      },
    };
  },
});
